import unittest
from order_dates import normalize_date

class OrderDates(unittest.TestCase):
    def test_calendar_formats(self):
        self.assertEqual(normalize_date('2024-02-29'), '2024-02-29')
        self.assertEqual(normalize_date('20240229'), '2024-02-29')
        self.assertEqual(normalize_date('20251203'), '2025-12-03')

    def test_week_dates_cross_calendar_year(self):
        self.assertEqual(normalize_date('2020-W53-7'), '2021-01-03')
        self.assertEqual(normalize_date('2024-W01-1'), '2024-01-01')

    def test_unsupported_and_invalid_dates(self):
        for text in ['2024', '2024-02', '2024-060', '2023-02-29', '2024-13-01', '2024-01-01T00:00:00']:
            with self.subTest(text=text), self.assertRaises(ValueError):
                normalize_date(text)

    def test_additional_documented_week_forms(self):
        self.assertEqual(normalize_date('2024W011'), '2024-01-01')
        self.assertEqual(normalize_date('2024-W01'), '2024-01-01')
        with self.assertRaises(ValueError):
            normalize_date('2021-W53-1')

if __name__ == '__main__':
    unittest.main()

